//! The contract: every vector generated by the Python reference
//! (scripts/golden_vectors.py -> node/vectors/golden.json) must reproduce
//! bit-exactly. If this fails, the Rust node is wrong — the rig is the spec.

use sestrian_core as core;
use serde_json::Value;

fn vectors() -> Value {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/../vectors/golden.json");
    serde_json::from_str(&std::fs::read_to_string(path).expect("golden.json missing"))
        .expect("golden.json invalid")
}

fn f64s(v: &Value) -> Vec<f64> {
    v.as_array().unwrap().iter().map(|x| x.as_f64().unwrap()).collect()
}
fn i64s(v: &Value) -> Vec<i64> {
    v.as_array().unwrap().iter().map(|x| x.as_i64().unwrap()).collect()
}

#[test]
fn quantize_matches_reference() {
    for case in vectors()["quantize"].as_array().unwrap() {
        assert_eq!(core::quantize(&f64s(&case["f"])), i64s(&case["q"]),
                   "quantize mismatch (round-half-to-even?)");
    }
}

#[test]
fn state_root_matches_reference() {
    for case in vectors()["state_root"].as_array().unwrap() {
        assert_eq!(core::state_root(&i64s(&case["w"])),
                   case["root"].as_str().unwrap(),
                   "state_root mismatch (endianness?)");
    }
}

#[test]
fn trimmed_mean_matches_reference() {
    for case in vectors()["trimmed_mean"].as_array().unwrap() {
        let deltas: Vec<Vec<i64>> = case["deltas"].as_array().unwrap()
            .iter().map(i64s).collect();
        assert_eq!(core::trimmed_mean(&deltas, 0.2), i64s(&case["mean"]),
                   "trimmed_mean mismatch (floor division?)");
    }
}

#[test]
fn delta_hash_matches_reference() {
    for case in vectors()["delta_hash"].as_array().unwrap() {
        let d = i64s(&case["delta"]);
        assert_eq!(core::delta_hash(&core::int64_bytes(&d)),
                   case["hash"].as_str().unwrap());
    }
}

#[test]
fn decompress_matches_reference() {
    for case in vectors()["decompress"].as_array().unwrap() {
        let idx = hex::decode(case["idx_hex"].as_str().unwrap()).unwrap();
        let val = hex::decode(case["val_hex"].as_str().unwrap()).unwrap();
        let n = case["n"].as_u64().unwrap() as usize;
        assert_eq!(core::decompress(n, &idx, &val), i64s(&case["dense"]));
    }
}

#[test]
fn ed25519_matches_reference() {
    for case in vectors()["ed25519"].as_array().unwrap() {
        let seed: [u8; 32] = hex::decode(case["seed_hex"].as_str().unwrap())
            .unwrap().try_into().unwrap();
        let key = core::Key::from_seed(seed);
        assert_eq!(key.pub_hex(), case["pub_hex"].as_str().unwrap(),
                   "pubkey derivation mismatch");
        let msg = hex::decode(case["msg_hex"].as_str().unwrap()).unwrap();
        assert_eq!(hex::encode(key.sign(&msg)), case["sig_hex"].as_str().unwrap(),
                   "signature mismatch (RFC 8032 is deterministic)");
        assert!(core::verify_sig(&key.pub_hex(), &msg,
                                 &hex::decode(case["sig_hex"].as_str().unwrap()).unwrap()));
    }
}

fn tx_from(t: &Value) -> core::BackpropTx {
    core::BackpropTx {
        miner: t["miner"].as_str().unwrap().into(),
        base_height: t["base_height"].as_u64().unwrap(),
        delta_hash: t["delta_hash"].as_str().unwrap().into(),
        da_pointer: t["da_pointer"].as_str().unwrap().into(),
        bond: t["bond"].as_u64().unwrap_or(0),
        pages: t["pages"].as_array().unwrap()
            .iter().map(|x| x.as_u64().unwrap() as u32).collect(),
        data_refs: t.get("data_refs").and_then(|v| v.as_array())
            .map(|a| a.iter().filter_map(|x| x.as_str().map(String::from)).collect())
            .unwrap_or_default(),
        sig: hex::decode(t["sig_hex"].as_str().unwrap()).unwrap(),
    }
}

#[test]
fn backprop_tx_matches_reference() {
    // v1: shard_id is gone; the signed PAGE CLAIM SET is count-prefixed in the
    // preimage between bond and data_refs.
    for case in vectors()["backprop_tx"].as_array().unwrap() {
        let tx = tx_from(case);
        assert_eq!(hex::encode(tx.signing_bytes()),
                   case["signing_bytes_hex"].as_str().unwrap());
        assert_eq!(tx.txid(), case["txid"].as_str().unwrap());
        assert!(tx.verify(), "tx signature must verify");
    }
}

#[test]
fn txset_root_matches_reference() {
    for case in vectors()["txset_root"].as_array().unwrap() {
        let ids: Vec<String> = case["txids"].as_array().unwrap()
            .iter().map(|x| x.as_str().unwrap().to_string()).collect();
        assert_eq!(core::txset_root(&ids), case["root"].as_str().unwrap());
    }
}

fn header_from(case: &Value) -> core::Header {
    core::Header {
        height: case["height"].as_u64().unwrap(),
        prev_hash: case["prev_hash"].as_str().unwrap().into(),
        state_root: case["state_root"].as_str().unwrap().into(),
        txset_root: case["txset_root"].as_str().unwrap().into(),
        n_txs: case["n_txs"].as_u64().unwrap(),
        work: case["work"].as_u64().unwrap(),
        proposer: case["proposer"].as_str().unwrap().into(),
        transfer_root: case["transfer_root"].as_str().unwrap_or("").into(),
        ledger_root: case["ledger_root"].as_str().unwrap_or("").into(),
        data_root: case["data_root"].as_str().unwrap_or("").into(),
        vrf_proof: case["vrf_proof"].as_str().unwrap_or("").into(),
        score_root: case["score_root"].as_str().unwrap_or("").into(),
        sketch_root: case["sketch_root"].as_str().unwrap_or("").into(),
        model_root: case["model_root"].as_str().unwrap_or("").into(),
        vrf_attempt: case["vrf_attempt"].as_u64().unwrap_or(0),
        version: case["version"].as_u64().unwrap_or(1),
    }
}

#[test]
fn header_hash_matches_reference() {
    for case in vectors()["header"].as_array().unwrap() {
        let h = header_from(case);
        assert_eq!(h.canonical_json(), case["canonical_json"].as_str().unwrap(),
                   "canonical JSON must match python json.dumps(sort_keys=True)");
        assert_eq!(h.block_hash(), case["hash"].as_str().unwrap());
    }
}

#[test]
fn address_and_emission_match_reference() {
    use sestrian_core::token;
    for case in vectors()["address"].as_array().unwrap() {
        assert_eq!(token::address(case["pub_hex"].as_str().unwrap()),
                   case["address"].as_str().unwrap());
    }
    for case in vectors()["emission"].as_array().unwrap() {
        assert_eq!(token::emission(case["height"].as_u64().unwrap()),
                   case["reward"].as_u64().unwrap(),
                   "emission schedule mismatch at height {}", case["height"]);
    }
}

fn transfer_from(t: &Value) -> sestrian_core::token::TransferTx {
    sestrian_core::token::TransferTx {
        from_pub: t["from_pub"].as_str().unwrap().into(),
        to_addr: t["to_addr"].as_str().unwrap().into(),
        amount: t["amount"].as_u64().unwrap(),
        nonce: t["nonce"].as_u64().unwrap(),
        sig: hex::decode(t["sig_hex"].as_str().unwrap()).unwrap(),
    }
}

#[test]
fn ledger_matches_reference() {
    use sestrian_core::token::{self, AccountTx, TokenLedger};
    for case in vectors()["ledger"].as_array().unwrap() {
        let miners: Vec<String> = case["miners"].as_array().unwrap()
            .iter().map(|x| x.as_str().unwrap().to_string()).collect();
        let data: Vec<String> = case["data_addrs"].as_array().unwrap()
            .iter().map(|x| x.as_str().unwrap().to_string()).collect();
        let mut led = TokenLedger::new();
        led.apply_reward(case["height"].as_u64().unwrap(), &miners,
                         case["proposer"].as_str().unwrap(), &data, &Default::default(),
                         &Default::default());
        assert_eq!(led.root(), case["root_after_reward"].as_str().unwrap(),
                   "reward split / ledger-root serialization mismatch");
        let tx = transfer_from(&case["transfer"]);
        assert_eq!(hex::encode(tx.signing_bytes()),
                   case["transfer"]["signing_bytes_hex"].as_str().unwrap());
        assert_eq!(AccountTx::Transfer(tx.clone()).txid(),
                   case["transfer"]["txid"].as_str().unwrap());
        assert!(led.apply_transfer(&tx), "reference transfer must apply");
        assert_eq!(led.root(), case["root_after_transfer"].as_str().unwrap());
        assert_eq!(token::transfer_root(&[tx]),
                   case["transfer_root"].as_str().unwrap());
        for (addr, bal) in case["balances"].as_object().unwrap() {
            assert_eq!(led.balance(addr), bal.as_u64().unwrap());
        }
    }
}

#[test]
fn data_provenance_matches_reference() {
    use sestrian_core::token::TokenLedger;
    use std::collections::BTreeMap;
    for case in vectors()["data_provenance"].as_array().unwrap() {
        let mut led = TokenLedger::new();
        let corpora = case["corpora"].as_object().unwrap();
        for (h, owner) in corpora {
            led.registry.insert(h.clone(), serde_json::json!({
                "owner": owner.as_str().unwrap(), "data_hash": h,
                "size": 0, "media_type": "text", "stake": 0,
                "weight": 1, "status": "active"}));
        }
        let credits: BTreeMap<String, u64> = case["data_credits"].as_object().unwrap()
            .iter().map(|(k, v)| (k.clone(), v.as_u64().unwrap())).collect();
        let miner = case["miner"].as_str().unwrap();
        led.apply_reward(case["height"].as_u64().unwrap(), &[miner.to_string()],
                         miner, &[], &credits, &Default::default());
        // only the NAMED corpus (A) is paid; the unnamed active corpus (B) earns 0
        assert_eq!(led.balance(case["owner_a"].as_str().unwrap()),
                   case["balance_a"].as_u64().unwrap(), "named corpus owner payout");
        assert_eq!(led.balance(case["owner_b"].as_str().unwrap()),
                   case["balance_b"].as_u64().unwrap(), "unnamed corpus must earn 0");
        assert_eq!(led.balance(&sestrian_core::token::address(miner)),
                   case["miner_after"].as_u64().unwrap(), "miner share");
        assert_eq!(led.root(), case["root"].as_str().unwrap(),
                   "provenance-payout ledger root mismatch");
    }
}

#[test]
fn scoring_matches_reference() {
    // rev 7: the miner pool splits ∝ committed delta scores; all-zero weights
    // fall back to the equal split. Roots lock the serialization.
    use sestrian_core::token::{address, TokenLedger};
    use std::collections::BTreeMap;
    for case in vectors()["scoring"].as_array().unwrap() {
        let a = case["miner_a"].as_str().unwrap();
        let b = case["miner_b"].as_str().unwrap();
        let h = case["height"].as_u64().unwrap();
        let weights: BTreeMap<String, u64> = case["weights"].as_object().unwrap()
            .iter().map(|(k, v)| (k.clone(), v.as_u64().unwrap())).collect();
        let mut led = TokenLedger::new();
        led.apply_reward(h, &[a.to_string(), b.to_string()], "genesis", &[],
                         &Default::default(), &weights);
        assert_eq!(led.balance(&address(a)), case["balance_a"].as_u64().unwrap(),
                   "3x-scored miner share");
        assert_eq!(led.balance(&address(b)), case["balance_b"].as_u64().unwrap(),
                   "1x-scored miner share");
        assert_eq!(led.root(), case["root"].as_str().unwrap());
        let mut led_z = TokenLedger::new();
        led_z.apply_reward(h, &[a.to_string(), b.to_string()], "genesis", &[],
                           &Default::default(), &Default::default());
        assert_eq!(led_z.balance(&address(a)), case["equal_balance_a"].as_u64().unwrap());
        assert_eq!(led_z.balance(&address(b)), case["equal_balance_b"].as_u64().unwrap());
        assert_eq!(led_z.root(), case["equal_root"].as_str().unwrap());
    }
}

#[test]
fn fee_flows_match_reference() {
    // rev 6: an inference fee splits 60/20/20 (server instant, data + training
    // slices into the ledger fee pools), and the NEXT block's reward drains the
    // pools to its delta miners + provenance-named data owners.
    use sestrian_core::token::{address, AccountTx, InferenceReceiptTx, TokenLedger};
    use std::collections::{BTreeMap, HashSet};
    for case in vectors()["fee_flows"].as_array().unwrap() {
        let payer = case["payer_pub"].as_str().unwrap();
        let mut led = TokenLedger::new();
        led.apply_reward(1, &[payer.to_string()], "genesis", &[], &Default::default(), &Default::default());
        let rcpt = AccountTx::InferenceReceipt(InferenceReceiptTx {
            payer_pub: payer.into(),
            server_addr: case["server_addr"].as_str().unwrap().into(),
            fee: case["fee"].as_u64().unwrap(),
            output_hash: case["output_hash"].as_str().unwrap().into(),
            head_root: case["head_root"].as_str().unwrap().into(),
            nonce: case["nonce"].as_u64().unwrap(),
            answer_sketch: vec![],
            sig: hex::decode(case["sig_hex"].as_str().unwrap()).unwrap(),
        });
        assert!(led.apply_data_tx(&rcpt, 1, &HashSet::new()), "receipt must apply");
        let s = &case["after_receipt"];
        assert_eq!(led.balance(case["server_addr"].as_str().unwrap()),
                   s["server_after"].as_u64().unwrap(), "server paid 60% + dust");
        assert_eq!(led.fee_data_pool, s["fee_data_pool"].as_u64().unwrap());
        assert_eq!(led.fee_train_pool, s["fee_train_pool"].as_u64().unwrap());
        assert_eq!(led.root(), s["root"].as_str().unwrap(), "post-receipt root");
        // register the corpus, then the next block drains both pools
        led.registry.insert("corpusF".into(), serde_json::json!({
            "owner": case["owner_f"].as_str().unwrap(), "data_hash": "corpusF",
            "size": 0, "media_type": "text", "stake": 0,
            "weight": 1, "status": "active"}));
        let credits: BTreeMap<String, u64> = [("corpusF".to_string(), 1u64)].into();
        let miner = case["miner"].as_str().unwrap();
        led.apply_reward(2, &[miner.to_string()], "genesis", &[], &credits, &Default::default());
        let d = &case["after_drain"];
        assert_eq!(led.balance(&address(miner)),
                   d["miner_after"].as_u64().unwrap(), "miner share + train pool");
        assert_eq!(led.balance(case["owner_f"].as_str().unwrap()),
                   d["owner_after"].as_u64().unwrap(), "data share + data pool");
        assert_eq!(led.fee_data_pool, d["fee_data_pool"].as_u64().unwrap());
        assert_eq!(led.fee_train_pool, d["fee_train_pool"].as_u64().unwrap());
        assert_eq!(led.root(), d["root"].as_str().unwrap(), "post-drain root");
    }
}

fn data_tx_from(kind: &str, t: &Value) -> sestrian_core::token::AccountTx {
    use sestrian_core::token::*;
    let sig = hex::decode(t["sig_hex"].as_str().unwrap()).unwrap();
    match kind {
        "submit" => AccountTx::DataSubmit(DataSubmitTx {
            owner_pub: t["owner_pub"].as_str().unwrap().into(),
            data_hash: t["data_hash"].as_str().unwrap().into(),
            size_bytes: t["size_bytes"].as_u64().unwrap(),
            media_type: t["media_type"].as_str().unwrap().into(),
            stake: t["stake"].as_u64().unwrap(),
            nonce: t["nonce"].as_u64().unwrap(),
            da_root: t["da_root"].as_str().unwrap_or("").into(),
            sig,
        }),
        "challenge" => AccountTx::DataChallenge(DataChallengeTx {
            challenger_pub: t["challenger_pub"].as_str().unwrap().into(),
            data_id: t["data_id"].as_str().unwrap().into(),
            stake: t["stake"].as_u64().unwrap(),
            reason: t["reason"].as_str().unwrap().into(),
            nonce: t["nonce"].as_u64().unwrap(), sig,
        }),
        _ => AccountTx::DataVote(DataVoteTx {
            voter_pub: t["voter_pub"].as_str().unwrap().into(),
            challenge_id: t["challenge_id"].as_str().unwrap().into(),
            support: t["support"].as_bool().unwrap(),
            nonce: t["nonce"].as_u64().unwrap(), sig,
        }),
    }
}

#[test]
fn data_lane_matches_reference() {
    use sestrian_core::token::{address, data_root, TokenLedger};
    use std::collections::HashSet;
    for case in vectors()["data_lane"].as_array().unwrap() {
        let mut led = TokenLedger::new();
        led.seed_genesis_data(&address(case["founder_pub"].as_str().unwrap()));
        assert_eq!(led.root(), case["root_genesis"].as_str().unwrap(),
                   "genesis registry serialization mismatch");
        let sub = data_tx_from("submit", &case["submit"]);
        assert_eq!(hex::encode(sub.signing_bytes()),
                   case["submit"]["signing_bytes_hex"].as_str().unwrap());
        assert_eq!(sub.txid(), case["submit"]["txid"].as_str().unwrap());
        // fund the submitter exactly as the reference did
        let owner = case["submit"]["owner_pub"].as_str().unwrap().to_string();
        led.apply_reward(1, &[owner.clone()], &owner, &[], &Default::default(), &Default::default());
        assert!(led.apply_data_tx(&sub, 1, &HashSet::new()));
        assert_eq!(led.root(), case["root_after_submit"].as_str().unwrap());
        let challenger = case["challenge"]["challenger_pub"].as_str().unwrap().to_string();
        led.apply_reward(2, &[challenger.clone()], &challenger, &[], &Default::default(), &Default::default());
        let ch = data_tx_from("challenge", &case["challenge"]);
        assert!(led.apply_data_tx(&ch, 2, &HashSet::new()));
        // CHALLENGE_QUORUM disinterested jurors vote to uphold
        let votes_json = case["votes"].as_array().unwrap();
        let votes: Vec<_> = votes_json.iter().map(|vj| data_tx_from("vote", vj)).collect();
        let jurors: HashSet<String> = votes.iter()
            .map(|v| v.sender_pub().to_string()).collect();
        for vote in &votes {
            assert!(led.apply_data_tx(vote, 3, &jurors), "quorum juror vote must apply");
        }
        assert_eq!(led.root(), case["root_after_vote"].as_str().unwrap());
        led.resolve_expired_challenges(case["resolve_height"].as_u64().unwrap());
        assert_eq!(led.root(), case["root_after_resolve"].as_str().unwrap(),
                   "challenge resolution mismatch");
        assert_eq!(led.balance(&sestrian_core::token::address(&challenger)),
                   case["challenger_balance_after"].as_u64().unwrap());
        let mut all = vec![sub, ch];
        all.extend(votes);
        assert_eq!(data_root(&all), case["data_root_of_all"].as_str().unwrap());
    }
}

fn spec_from(s: &Value) -> core::model_state::ModelSpec {
    core::model_state::ModelSpec {
        n_layers: s["n_layers"].as_u64().unwrap(),
        d_model: s["d_model"].as_u64().unwrap(),
        d_ff: s["d_ff"].as_u64().unwrap(),
        n_experts_initial: s["n_experts_initial"].as_u64().unwrap(),
        e_max: s["e_max"].as_u64().unwrap(),
        backbone_params: s["backbone_params"].as_u64().unwrap(),
    }
}

fn params_from(spec: core::model_state::ModelSpec, p: &Value) -> core::model_state::GenesisParams {
    core::model_state::GenesisParams {
        spec,
        retarget_window: p["retarget_window"].as_u64().unwrap(),
        target_deltas: p["target_deltas"].as_i64().unwrap(),
        quota_min_4dp: p["quota_min_4dp"].as_i64().unwrap(),
        quota_max_4dp: p["quota_max_4dp"].as_i64().unwrap(),
        stale_ceiling_4dp: p["stale_ceiling_4dp"].as_i64().unwrap(),
        k_sustain: p["k_sustain"].as_i64().unwrap(),
        growth_bound: p["growth_bound"].as_i64().unwrap(),
        announce_lead: p["announce_lead"].as_u64().unwrap(),
        delta_max_nnz: 1_000_000,
        v3_height: 1_000_000_000,
        v4_height: 1_000_000_000,
        growth_quorum: 3,
    }
}

fn pages_from(v: &Value) -> Vec<core::model_state::Page> {
    v.as_array().unwrap().iter().map(|p| {
        let a = p.as_array().unwrap();
        core::model_state::Page {
            start: a[0].as_u64().unwrap(),
            end: a[1].as_u64().unwrap(),
            kind: a[2].as_str().unwrap().into(),
            layer: a[3].as_i64().unwrap(),
            expert: a[4].as_i64().unwrap(),
            status: a[5].as_str().unwrap().into(),
        }
    }).collect()
}

#[test]
fn full_chain_replay_matches_reference() {
    // v1: a mini MoE chain with page-claimed deltas, eligibility attempts, a
    // fork, transfers, a data submit, window rollovers, AND an on-chain growth
    // activation with a post-growth block. Rust must rebuild every block,
    // validate it completely, run fork choice, and land on the same head with
    // the same roots — bit-exact ACROSS the dimension change.
    use sestrian_core::blocktree::{Block, BlockTree};
    use sestrian_core::model_state::{fold, page_init, page_state_root, ModelState};
    use std::collections::HashMap;
    for case in vectors()["chain_replay"].as_array().unwrap() {
        let spec = spec_from(&case["spec"]);
        let params = params_from(spec.clone(), &case["params"]);
        let genesis_w = i64s(&case["genesis_w"]);
        let mut tree = BlockTree::new(
            genesis_w.clone(),
            Some(case["data_contributor"].as_str().unwrap().into()),
            params.clone());
        for b in case["blocks"].as_array().unwrap() {
            let header = header_from(&b["header"]);
            assert_eq!(header.block_hash(), b["hash"].as_str().unwrap(),
                       "header serialization drift");
            let txs: Vec<core::BackpropTx> =
                b["txs"].as_array().unwrap().iter().map(tx_from).collect();
            let bodies: HashMap<String, Vec<i64>> = b["bodies"].as_object().unwrap()
                .iter().map(|(k, v)| (k.clone(), i64s(v))).collect();
            let transfers = b["transfers"].as_array().unwrap()
                .iter().map(transfer_from).collect();
            let data_txs = b["data_txs"].as_array().unwrap()
                .iter().map(|t| data_tx_from("submit", t)).collect();
            // full first-principles validation: sigs, DA hashes, page claims,
            // quota, eligibility, per-page transition + growth activation,
            // txset/score/sketch/transfer/data/ledger roots — then fork choice
            let scores: std::collections::BTreeMap<String, u64> =
                b.get("scores").and_then(|v| v.as_object())
                    .map(|m| m.iter()
                        .filter_map(|(k, x)| x.as_u64().map(|s| (k.clone(), s)))
                        .collect())
                    .unwrap_or_default();
            let sketches: std::collections::BTreeMap<String, Vec<i32>> =
                b.get("sketches").and_then(|v| v.as_object())
                    .map(|m| m.iter()
                        .filter_map(|(k, x)| x.as_array().map(|a| (
                            k.clone(),
                            a.iter().map(|e| e.as_i64().unwrap_or(0) as i32).collect(),
                        )))
                        .collect())
                    .unwrap_or_default();
            tree.add_block(Block { header, txs, bodies, sparse: HashMap::new(), transfers, data_txs, scores,
                                   sketches })
                .expect("reference block must validate");
        }
        assert_eq!(tree.head, case["expected_head"].as_str().unwrap(),
                   "fork choice disagrees with reference");
        // THE RESTART-WEDGE INVARIANT, checked on a real forked chain.
        // Fast-boot cannot adopt a rival of its own snapshot block: connecting
        // that rival needs the PARENT state, which lies below the checkpoint.
        // So a snapshot taken AT the head puts the state floor exactly where a
        // live proposal tie can exist, and a node restarted onto the losing
        // side of one can never rejoin — how the EU anchor (tie at 252) and
        // then the US anchor (tie at 276) each wedged for hours. Checkpointing
        // the head's PARENT keeps every head tie above the floor.
        let head_h = tree.blocks[&tree.head].height;
        if head_h >= 2 {
            let (basis, basis_state) = tree.snapshot_basis();
            assert_ne!(basis, tree.head,
                       "snapshot must NOT checkpoint the head — that is the \
                        restart-wedge that stranded two anchors");
            assert_eq!(basis, tree.blocks[&tree.head].prev_hash,
                       "snapshot must checkpoint the head's parent");
            assert_eq!(basis_state.len(), tree.head_state().len(),
                       "checkpoint state must be a usable full weight vector");
        }
        assert_eq!(page_state_root(tree.head_state(), tree.head_model()),
                   case["expected_state_root"].as_str().unwrap());
        assert_eq!(tree.head_model().model_root(),
                   case["expected_model_root"].as_str().unwrap());
        assert_eq!(tree.head_model().dim(), case["expected_dim"].as_u64().unwrap(),
                   "growth must have extended the state");
        assert_eq!(tree.head_model().pages.len(),
                   case["expected_n_pages"].as_u64().unwrap() as usize);
        assert_eq!(tree.head_ledger().root(),
                   case["expected_ledger_root"].as_str().unwrap());
        assert_eq!(tree.head_ledger().supply(),
                   case["expected_supply"].as_u64().unwrap());
        assert_eq!(tree.blocks[&tree.head].height,
                   case["expected_head_height"].as_u64().unwrap());

        // Independent full replay from genesis (§3.5): re-apply every head-chain
        // block's per-page transitions AND the ModelState fold, including the
        // growth activation (page append) — bit-exact across the dim change.
        let by_hash: HashMap<&str, &Value> = case["blocks"].as_array().unwrap()
            .iter().map(|b| (b["hash"].as_str().unwrap(), b)).collect();
        let mut chain: Vec<&Value> = Vec::new();
        let mut cur = case["expected_head"].as_str().unwrap();
        while cur != tree.genesis_hash {
            let b = by_hash[cur];
            chain.push(b);
            cur = b["parent"].as_str().unwrap();
        }
        chain.reverse();
        let mut w = genesis_w.clone();
        let mut model = ModelState::genesis(&params.spec);
        for b in chain {
            let txs: Vec<core::BackpropTx> =
                b["txs"].as_array().unwrap().iter().map(tx_from).collect();
            let bodies: Vec<Vec<i64>> = txs.iter()
                .map(|t| i64s(&b["bodies"][&t.da_pointer])).collect();
            let claims: Vec<Vec<u32>> = txs.iter().map(|t| t.canonical_pages()).collect();
            let spans: Vec<(u64, u64)> =
                model.pages.iter().map(|p| (p.start, p.end)).collect();
            w = core::paged_transition(&w, &bodies, &claims, &spans);
            let zero_scored = txs.iter()
                .filter(|t| b["scores"][&t.txid()].as_u64().unwrap_or(0) == 0)
                .count() as u64;
            let h = &b["header"];
            let score_sum: u64 = txs.iter()
                .map(|t| b["scores"][&t.txid()].as_u64().unwrap_or(0)).sum();
            let (next, activations) = fold(&model, &params,
                                           h["height"].as_u64().unwrap(),
                                           txs.len() as u64, zero_scored,
                                           h["prev_hash"].as_str().unwrap(),
                                           score_sum,
                                           h["proposer"].as_str().unwrap_or(""));
            model = next;
            for (page_id, _l, _e, trigger) in &activations {
                w.extend(page_init(trigger, *page_id, &params.spec));
            }
        }
        assert_eq!(page_state_root(&w, &model),
                   case["replay_state_root"].as_str().unwrap(),
                   "replay from genesis must be bit-exact across the dim change");
    }
}

#[test]
fn page_root_matches_reference() {
    // v1 state commitment: domain-separated page-Merkle root over page bytes
    // (0x00 leaf / 0x01 node, odd node promoted by hashing with itself).
    use sestrian_core::model_state::{page_state_root, ModelState};
    for case in vectors()["page_root"].as_array().unwrap() {
        let w = i64s(&case["w"]);
        let pages = pages_from(&case["pages"]);
        if let Some(leaf0) = case.get("leaf0_hex").and_then(|x| x.as_str()) {
            let p0 = &pages[0];
            let bytes = core::int64_bytes(&w[p0.start as usize..p0.end as usize]);
            assert_eq!(hex::encode(core::merkle::leaf_hash(&bytes)), leaf0,
                       "leaf hash (0x00 domain separation)");
        }
        let st = ModelState {
            pages,
            quota_4dp: 10_000,
            pinned_streak: 0,
            slack_streak: 0,
            pending_growth: vec![],
            window_id: 0,
            win_accepted: 0,
            win_zero_scored: 0,
            win_score_sum: 0,
            rev: 2,
            win_scorers: vec![],
            events_total: 0,
        };
        assert_eq!(page_state_root(&w, &st), case["root"].as_str().unwrap(),
                   "page-Merkle root mismatch");
    }
}

