#[test]
fn sketches_match_reference() {
    // rev 8: sketch_root canonical form, the alignment-split receipt (aligned ->
    // owner paid directly, anti-aligned -> pooled), signing-bytes parity for
    // the answer_sketch framed field. Delta-sketch VALUES are committed data
    // (the hash projection lives in the rig only), so the vector supplies them.
    use sestrian_core::blocktree::{sketch_root, SKETCH_DIM};
    use sestrian_core::token::{AccountTx, InferenceReceiptTx, TokenLedger};
    use std::collections::{BTreeMap, HashSet};
    for case in vectors()["sketches"].as_array().unwrap() {
        let sk: Vec<i32> = case["sketch"].as_array().unwrap()
            .iter().map(|x| x.as_i64().unwrap() as i32).collect();
        assert_eq!(sk.len(), SKETCH_DIM);
        let m: BTreeMap<String, Vec<i32>> = [("tx0".to_string(), sk)].into();
        assert_eq!(sketch_root(&m), case["sketch_root"].as_str().unwrap(),
                   "sketch_root canonical JSON drift");
        let dim = case["dim"].as_u64().unwrap() as usize;
        let owner = case["owner"].as_str().unwrap();
        let payer = case["payer"].as_str().unwrap();
        let mut led = TokenLedger::new();
        led.registry.insert("corpusS".into(), serde_json::json!({
            "owner": owner, "data_hash": "corpusS", "size": 0,
            "media_type": "text", "stake": 0, "weight": 1, "status": "active",
            "sketch": vec![case["corpus_sketch_entry"].as_i64().unwrap(); dim]}));
        led.apply_reward(1, &[payer.to_string()], "genesis", &[],
                         &Default::default(), &Default::default());
        let mk = |nonce: u64, entry: i64, sig_hex: &str| {
            AccountTx::InferenceReceipt(InferenceReceiptTx {
                payer_pub: payer.into(),
                server_addr: case["server"].as_str().unwrap().into(),
                fee: case["fee"].as_u64().unwrap(),
                output_hash: "aa".repeat(32), head_root: "bb".repeat(32),
                nonce,
                answer_sketch: vec![entry; dim],
                sig: hex::decode(sig_hex).unwrap(),
            })
        };
        let a = &case["aligned"];
        let pos = mk(0, a["answer_entry"].as_i64().unwrap(),
                     a["sig_hex"].as_str().unwrap());
        if let AccountTx::InferenceReceipt(t) = &pos {
            assert_eq!(hex::encode(t.signing_bytes()),
                       a["signing_bytes_hex"].as_str().unwrap(),
                       "answer_sketch framed-field drift");
        }
        assert!(led.apply_data_tx(&pos, 2, &HashSet::new()));
        assert_eq!(led.balance(owner), a["owner_after"].as_u64().unwrap(),
                   "aligned answer must pay the owner directly");
        assert_eq!(led.fee_data_pool, a["fee_data_pool_after"].as_u64().unwrap());
        assert_eq!(led.root(), a["root_after"].as_str().unwrap());
        let n = &case["anti"];
        let neg = mk(1, n["answer_entry"].as_i64().unwrap(),
                     n["sig_hex"].as_str().unwrap());
        if let AccountTx::InferenceReceipt(t) = &neg {
            assert_eq!(hex::encode(t.signing_bytes()),
                       n["signing_bytes_hex"].as_str().unwrap());
        }
        assert!(led.apply_data_tx(&neg, 3, &HashSet::new()));
        assert_eq!(led.balance(owner), n["owner_after"].as_u64().unwrap(),
                   "anti-aligned answer must NOT pay the owner");
        assert_eq!(led.fee_data_pool, n["fee_data_pool_after"].as_u64().unwrap());
        assert_eq!(led.root(), n["root_after"].as_str().unwrap());
    }
}


#[test]
fn v4_fold_matches_reference() {
    // v4: the QUORUM gate. Pins the activation boundary (win_scorers enters
    // the canonical JSON exactly at v4_height), proposer dedupe, the quorum
    // cap, the anonymous-proposer rule, the window reset, and both gate
    // outcomes to the Python reference — the whole rule, byte for byte.
    use sestrian_core::model_state::{fold, GenesisParams, ModelState};
    let v = vectors();
    let case = &v["v4_fold"][0];
    let spec = spec_from(&v["controller_fold"][0]["spec"]);
    let mut params = GenesisParams::new(spec);
    params.retarget_window = case["retarget_window"].as_u64().unwrap();
    params.target_deltas = case["target_deltas"].as_i64().unwrap();
    params.quota_max_4dp = case["quota_max_4dp"].as_i64().unwrap();
    params.k_sustain = case["k_sustain"].as_i64().unwrap();
    params.announce_lead = case["announce_lead"].as_u64().unwrap();
    params.v3_height = case["v3_height"].as_u64().unwrap();
    params.v4_height = case["v4_height"].as_u64().unwrap();
    params.growth_quorum = case["growth_quorum"].as_u64().unwrap() as usize;
    let mut st = ModelState::genesis(&params.spec);
    for step in case["steps"].as_array().unwrap() {
        let (next, acts) = fold(&st, &params,
                                step["height"].as_u64().unwrap(),
                                step["n_txs"].as_u64().unwrap(),
                                step["zero_scored"].as_u64().unwrap(),
                                step["prev_hash"].as_str().unwrap(),
                                step["score_sum"].as_u64().unwrap(),
                                step["proposer"].as_str().unwrap());
        st = next;
        assert_eq!(st.rev, step["rev"].as_u64().unwrap(),
                   "v4 rev diverged at h{}", step["height"]);
        let want: Vec<String> = step["win_scorers"].as_array().unwrap().iter()
            .map(|x| x.as_str().unwrap().to_string()).collect();
        assert_eq!(st.win_scorers, want,
                   "v4 scorer set diverged at h{}", step["height"]);
        assert_eq!(st.model_root(), step["model_root"].as_str().unwrap(),
                   "v4 fold diverged at h{}", step["height"]);
        assert_eq!(acts.len(), step["activations"].as_array().unwrap().len());
    }
    assert_eq!(st.events_total, case["final_events"].as_u64().unwrap());
    assert_eq!(st.pending_growth.len(),
               case["final_pending"].as_array().unwrap().len());
}

#[test]
fn v3_fold_matches_reference() {
    // v3: the scheduled-upgrade boundary (rev + win_score_sum enter the
    // canonical JSON exactly at v3_height) and the LEARNING GATE (growth
    // requires the window's summed committed scores > 0). Pins the entire
    // activation sequence to the Python reference.
    use sestrian_core::model_state::{fold, GenesisParams, ModelState};
    let v = vectors();
    let case = &v["v3_fold"][0];
    let spec = spec_from(&v["controller_fold"][0]["spec"]);
    let mut params = GenesisParams::new(spec);
    params.retarget_window = case["retarget_window"].as_u64().unwrap();
    params.target_deltas = case["target_deltas"].as_i64().unwrap();
    params.quota_max_4dp = case["quota_max_4dp"].as_i64().unwrap();
    params.k_sustain = case["k_sustain"].as_i64().unwrap();
    params.announce_lead = case["announce_lead"].as_u64().unwrap();
    params.v3_height = case["v3_height"].as_u64().unwrap();
    let mut st = ModelState::genesis(&params.spec);
    for step in case["steps"].as_array().unwrap() {
        let (next, acts) = fold(&st, &params,
                                step["height"].as_u64().unwrap(),
                                step["n_txs"].as_u64().unwrap(),
                                step["zero_scored"].as_u64().unwrap(),
                                step["prev_hash"].as_str().unwrap(),
                                step["score_sum"].as_u64().unwrap(), "");
        st = next;
        assert_eq!(st.rev, step["rev"].as_u64().unwrap());
        assert_eq!(st.model_root(), step["model_root"].as_str().unwrap(),
                   "v3 fold diverged at h{}", step["height"]);
        assert_eq!(acts.len(),
                   step["activations"].as_array().unwrap().len());
    }
    assert_eq!(st.events_total, case["final_events"].as_u64().unwrap());
    assert_eq!(st.pending_growth.len(),
               case["final_pending"].as_array().unwrap().len());
}

/// §7.2a corpus availability: the chunking and the two-level Merkle
/// construction, pinned to the Python reference. A port that chunked at a
/// different size, ordered chunk roots differently, or hashed the manifest
/// another way would still emit a 64-hex string — and would silently accept
/// corpora the reference rejects, which is the failure this vector exists to
/// catch. Spans a partial tail chunk in both directions.
#[test]
fn corpus_da_matches_reference() {
    use core::corpus;
    let v = vectors();
    let f = &v["corpus_da"][0];

    assert_eq!(f["chunk_bytes"].as_u64().unwrap(), corpus::CHUNK_BYTES as u64,
               "CHUNK_BYTES is consensus-critical: it determines every da_root");
    assert_eq!(f["chunk_k"].as_u64().unwrap(), corpus::CHUNK_K as u64);
    assert_eq!(f["chunk_n"].as_u64().unwrap(), corpus::CHUNK_N as u64);

    for case in f["cases"].as_array().unwrap() {
        let n = case["size_bytes"].as_u64().unwrap() as usize;
        // rebuild the exact body the generator used
        let pattern = b"sestrian-corpus-vector|";
        let mut body = Vec::with_capacity(n);
        while body.len() < n {
            body.extend_from_slice(pattern);
        }
        body.truncate(n);

        let m = corpus::build(&body[..]).unwrap();
        assert_eq!(m.data_hash, case["body_sha256"].as_str().unwrap(),
                   "corpus sha256 diverged at size {n}");
        assert_eq!(corpus::chunk_count(n as u64),
                   case["expected_chunks"].as_u64().unwrap(),
                   "chunk count diverged at size {n}");
        let want_roots: Vec<String> = case["chunk_roots_hex"].as_array().unwrap()
            .iter().map(|r| r.as_str().unwrap().to_string()).collect();
        let got_roots: Vec<String> = m.chunk_roots.iter().map(hex::encode).collect();
        assert_eq!(got_roots, want_roots, "chunk roots diverged at size {n}");
        assert_eq!(m.da_root, case["expected_da_root"].as_str().unwrap(),
                   "da_root diverged at size {n}");
    }
}
